text:
& li {
  &.tls-error > .container {
    & > .icon {
      --icon-color: var(--color-text-critical) !important;
    }

    & > .name {
      color: var(--color-text-critical);
    }

    & > .status-icon {
      background-image: var(--icon-warning);
      color: var(--folder-color-warning);
    }
  }

  &[data-server-type] > .container > .icon {
    --icon-color: var(--primary);
  }

  &:is([data-server-type="imap"], [data-server-type="pop3"], [data-server-type="ews"], [data-server-type="graph"]) > .container > .icon {
    content: var(--icon-mail);
  }

  &:is([data-server-type="imap"], [data-server-type="pop3"], [data-server-type="ews"], [data-server-type="graph"])[data-server-secure="true"]
    > .container
    > .icon {
    content: var(--icon-mail-secure);
  }

  &[data-server-type="none"] > .container > .icon {
    content: var(--icon-folder);
  }

  &[data-server-type="nntp"] > .container > .icon {
    content: var(--icon-globe);
  }

  &[data-server-type="nntp"][data-server-secure="true"] > .container > .icon {
    content: var(--icon-globe-secure);
  }

  &[data-server-type="rss"] > .container > .icon {
    content: var(--icon-rss);
  }

  &[data-server-type="rss"] > ul > li:not([data-folder-type], [data-is-busy="true"], [data-has-error="true"]) .icon {
    --icon-color: currentColor;
    fill: var(--icon-color);
  }
